## Immediate-Mode GUI

### Basic Window

```xiom
use xiom.imgui;

fn render_ui() {
  imgui::begin("My Tool");

  imgui::text("Hello from ImGui!");
  imgui::separator();

  if imgui::button("Click Me") {
    io.println("Button clicked!");
  }

  imgui::same_line();
  imgui::text("Buttons are inline now");

  imgui::end();
}
```

### Widgets

```xiom
// Slider
let mut volume = 0.5;
imgui::slider_float("Volume", &mut volume, 0.0, 1.0);

// Checkbox
let mut show_debug = false;
imgui::checkbox("Show Debug", &mut show_debug);

// Color picker
let mut color = [1.0, 0.5, 0.0];  // RGB
imgui::color_edit3("Color", &mut color);

// Input text
let mut buffer = StrBuf::new(256);
imgui::input_text("Name", &mut buffer);

// Combo box
let items = ["Option A", "Option B", "Option C"];
let mut selected = 0;
imgui::combo("Select", &mut selected, &items);

// Tree nodes
if imgui::treenode("Advanced Settings") {
  imgui::slider_float("Threshold", &mut threshold, 0.0, 1.0);
  imgui::tree_pop();
}
```

### Layout

```xiom
// Columns
imgui::columns(2);
imgui::text("Left column");
imgui::next_column();
imgui::text("Right column");
imgui::columns(1);

// Child windows (scrollable regions)
imgui::begin_child("scrollable", 200, 300);
for item in items {
  imgui::text(item);
}
imgui::end_child();

// Dockspace (full window docking)
imgui::dockspace("main_dock");
```

### Debug UI Pattern

```xiom
// Toggle with F3
if input.is_key_just_pressed(Key::F3) {
  show_debug_ui = !show_debug_ui;
}

if show_debug_ui {
  imgui::begin("Debug");
  imgui::text("FPS: " + (1.0 / delta_time).to_str());
  imgui::text("Draw calls: " + draw_calls.to_str());
  imgui::text("Memory: " + (allocated_mb).to_str() + " MB");
  imgui::end();
}
```

### Main Loop Integration

```xiom
while !window.should_close() {
  imgui::new_frame();

  render_ui();  // All UI calls go here

  imgui::render();
  window.swap_buffers();
  glfw::poll_events();
}
```

